using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckBuzkashi.Editor {
public static class BuzNameplateAuthoring {
 public static void Upgrade(){var scene=EditorSceneManager.OpenScene(BuzAuthoring.Scene);Install(Object.FindAnyObjectByType<BuzMatch>());EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
 public static void Install(BuzMatch match){var plates=match.GetComponent<BuzNameplates>();if(plates==null){BuzAuthoring.InstallLabels(match);plates=match.GetComponent<BuzNameplates>();}plates.carriers=new GameObject[6];var theme=Resources.Load<SportsBroadcastTheme>("SportsBroadcastTheme");
  for(int i=0;i<6;i++){var rect=plates.plates[i];rect.sizeDelta=new Vector2(150,26);var backing=rect.GetComponent<Image>();if(backing!=null)Object.DestroyImmediate(backing);var label=plates.captions[i];label.font=theme.bodyFont;label.fontSize=22;label.fontSizeMin=20;label.fontSizeMax=22;label.enableAutoSizing=false;label.rectTransform.sizeDelta=new Vector2(144,26);label.extraPadding=true;string path="Assets/TruckBuzkashi/Materials/Outlined team name "+(i<3?"Blue":"Orange")+".mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(material==null){material=new Material(theme.bodyFont.material);material.SetFloat("_OutlineWidth",.24f);material.SetColor("_OutlineColor",i<3?new Color(.005f,.055f,.16f):new Color(.18f,.045f,.005f));material.EnableKeyword("OUTLINE_ON");material.SetColor("_UnderlayColor",new Color(0,0,0,.9f));material.SetFloat("_UnderlayOffsetY",-1);material.SetFloat("_UnderlaySoftness",.2f);material.EnableKeyword("UNDERLAY_ON");AssetDatabase.CreateAsset(material,path);}label.fontSharedMaterial=material;label.UpdateMeshPadding();var prior=rect.Find("Small tow carrier marker");var marker=prior!=null?prior.gameObject:SportsUIAuthoring.Rect("Small tow carrier marker",rect,new Vector2(10,10),Vector2.zero);var image=marker.GetComponent<Image>()??marker.AddComponent<Image>();image.sprite=AssetDatabase.GetBuiltinExtraResource<Sprite>("UI/Skin/Knob.psd");image.color=new Color(1,.78f,.2f);image.raycastTarget=false;var markerRect=marker.GetComponent<RectTransform>();markerRect.anchorMin=markerRect.anchorMax=new Vector2(1,.5f);markerRect.anchoredPosition=new Vector2(8,0);marker.SetActive(false);plates.carriers[i]=marker;EditorUtility.SetDirty(label);EditorUtility.SetDirty(rect);}
  EditorUtility.SetDirty(plates);
 }
}
